<script lang="ts">
  import {statusHelp,modelHelp,statusColor} from '../data/analysis-copy';
  import type { Race, Runner, RunnerSample } from '../data/types';
  import type { RaceAnalysis } from '../data/analytics';
  import { analyticsAt } from '../data/analytics';
  import { skillName, runnerName, runnerOutfit, type ReferenceData } from '../data/reference';
  import UmaPortrait from './UmaPortrait.svelte';
  import GameIcon from './GameIcon.svelte';
  import StatBreakdown from './StatBreakdown.svelte';
  import RunnerEffects from './RunnerEffects.svelte';
  import StrategyBadge from './StrategyBadge.svelte';
  import StarRating from './StarRating.svelte';
  import { aptitudeLetter, skillIconKey, strategyLabel } from '../data/game-icons';
  import type { CourseReference } from '../data/reference';
  import { combinedStatusIntervals, statusShortLabel } from '../data/status-presentation';
  import { compareDisplayedSkills, effectiveStrategyCode, skillTone, skillToneColor, uniqueLevelLabel } from '../data/skill-details';
  import { statKeys } from '../data/race-stats';
  import { motionFor } from '../data/motion-analysis';
  import { modeImpactsFor } from '../data/status-mode-impact';
  import type { MotionBand } from '../data/race-motion';
  import type { StatKey, StatBreakdown as StatParts } from '../data/effect-types';
  export let runner:Runner, reference:ReferenceData|null, analysis:RaceAnalysis, time:number;
  export let sample:RunnerSample|undefined;
  export let gap:number|null=null;
  export let race:Race;
  export let course:CourseReference|null;
  export let onSkill:(id:number)=>void;
  export let onSeek:(time:number)=>void;
  export let onDownload:()=>void;
  let tab='skills';
  $: detail=analysis.runners[runner.id];
  $: motion=motionFor(race,reference,analysis,runner.id,course?.id);
  $: modes=modeImpactsFor(race,reference,analysis,runner.id,course?.id);
  function effectiveStat(stat:StatParts|undefined,band:MotionBand|null){const exact=stat?.final;return exact!=null?f(exact,0):band?Math.round(band.min)===Math.round(band.max)?f(band.mid,0):`${Math.round(band.min)}–${Math.round(band.max)}`:'—';}
  $: displayRunner={...runner,strategyCode:effectiveStrategyCode(runner,detail?.skillRows??[])};
  $: raceDistance=course?.distance??race.distance;
  $: distanceKey=!raceDistance?null:raceDistance<=1400?'short':raceDistance<=1800?'mile':raceDistance<=2400?'middle':'long';
  $: strategyKey=({Front:'front',Runaway:'front',Pace:'pace',Late:'late',End:'end'} as const)[strategyLabel(displayRunner) as 'Front'|'Runaway'|'Pace'|'Late'|'End'];
  $: aptitudeFacts=[['Distance',distanceKey?runner.aptitudes?.[distanceKey as 'short'|'mile'|'middle'|'long']:null],['Surface',course?.surface===1?runner.aptitudes?.turf:course?.surface===2?runner.aptitudes?.dirt:null],['Style',strategyKey?runner.aptitudes?.[strategyKey]:null]] as const;
  $: summary=detail?.summary;
  $: skillRows=[...(detail?.skillRows??[])].sort((a,b)=>compareDisplayedSkills(reference,a.skillId,b.skillId));
  $: displayIntervals=combinedStatusIntervals(detail?.intervals??[],{includeModels:true}).filter(s=>s.kind!=='downhill-section');
  $: activeStatuses=displayIntervals.filter(status=>time>=status.start&&(status.end===null?time<=(status.observedUntil??status.start):time<status.end));
  $: current=analyticsAt(analysis,runner.id,time);
  const f=(v:number|null|undefined,d=1)=>v==null?'—':v.toFixed(d);
  const statNames:Record<StatKey,string>={speed:'Speed',stamina:'Stamina',power:'Power',guts:'Guts',wisdom:'Wit'};
  function effectiveHelp(stat:StatParts|undefined):string {
    if(!stat)return 'Race bonuses unavailable.';
    const parts:[string,number|null][]=[['Over 1200',stat.raw!==null&&stat.overcap!==null?stat.overcap-stat.raw:null],['Mood',stat.moodGain],['Base limit',stat.baseCapGain],['Course',stat.courseGain],['Style',stat.strategyGain],['Ground',stat.groundGain],['Career',stat.careerGain],['Green skills',stat.passiveGain],['Limit',stat.capGain]];
    const changes=parts.filter(([,value])=>value===null||Math.abs(value)>.0001).map(([label,value])=>`${label}: ${value===null?'unknown':`${value>0?'+':''}${Number(value.toFixed(1))}`}`);
    const held=stat.final===null?stat.detail.match(/Final [^.]+\./)?.[0]??null:null;
    return [`Base: ${f(stat.raw,0)}`,...changes,`Effective: ${stat.final===null?'withheld':Number(stat.final.toFixed(1))}`,...(held?[held]:[])].join('\n');
  }
  const mood=(m:number|null|undefined)=>m==null?'—':({1:'Awful',2:'Bad',3:'Normal',4:'Good',5:'Great'} as Record<number,string>)[m]??String(m);
  const aptitudeGroups=[['Distance',[['Short','short'],['Mile','mile'],['Medium','middle'],['Long','long']]],['Surface',[['Turf','turf'],['Dirt','dirt']]],['Style',[['Front','front'],['Pace','pace'],['Late','late'],['End','end']]]] as const;
  $: metricGroups=summary?[
    ['Finish',[['Time',f(summary.rawTime,3),'s'],['Gap',f(summary.gap,3),'s'],['Behind at the win',f(summary.finishGapDistance),'m'],['Start delay',f(summary.startDelay==null?null:summary.startDelay*1000,1),'ms']]],
    ['HP',[['Start',f(summary.hpStart),''],['Finish',f(summary.hpFinish),''],['Lowest',f(summary.minimumHp),''],['Spent',f(summary.hpUsed),''],['Gained',f(summary.hpRecovered),''],['Empty at',f(summary.hpZeroTime),'s']]],
    ['Speed',[['Top',f(summary.maxSpeed,2),'m/s'],['Average',f(summary.meanSpeed,2),'m/s'],['Time in front',f(summary.leadTime),'s'],['Largest lead',f(summary.maximumLeadGap),'m']]],
    ['Final spurt',[['Started',summary.spurtDistance===-1?'None':f(summary.spurtDistance),'m'],['Late by',f(summary.spurtDelayDistance),'m'],['Duration',f(summary.spurtTime),'s'],['Speed',f(summary.spurtSpeed,2),'m/s']]],
    ['Trouble',[['Rushed',f(summary.rushedDuration),'s'],['Blocked',f(summary.blockedDuration),'s']]],
  ]:[];
</script>
<aside class="panel runner-panel" aria-label="Selected runner">
  <div class="runner-panel-header"><div class="eyebrow">SELECTED UMA</div><div class="runner-identity"><UmaPortrait {runner} size={48}/><div><h2>{runnerName(reference,runner)}</h2><span class="muted">{runnerOutfit(reference,runner)??runner.strategy??'Style unknown'}</span></div></div><div class="runner-actions"><button class="simulator-launch" onclick={onDownload}>Download Uma JSON</button></div></div>
  <div class="live-stats"><div><small>SPEED</small><strong>{f(sample?.speed,2)}<em>m/s</em></strong></div><div><small>HP</small><strong>{f(sample?.hp,0)}<em>/ {f(summary?.hpStart,0)}</em></strong></div><div><small title="Positive behind first; negative ahead of second.">GAP</small><strong>{f(gap)}<em>m</em></strong></div><div><small>ACCELERATION</small><strong>{f(current.sample?.acceleration,2)}<em>m/s²</em></strong></div></div>
  <div class="active-statuses">{#each activeStatuses as status}<span style={`--status:${statusColor(status.kind)}`} title={statusHelp(status.kind)}>{statusShortLabel(status.kind)}</span>{:else}<small>No status detected</small>{/each}</div>
  <div class="build-stats">
    {#each statKeys as stat}<div><GameIcon name={`stat-${stat}`} label={statNames[stat]} size={19}/><small>{({speed:'SPD',stamina:'STA',power:'POW',guts:'GUT',wisdom:'WIT'} as Record<StatKey,string>)[stat]}</small><strong>{f(runner.stats?.[stat],0)}</strong></div>{/each}
    <span class="effective-label" title="Starting race stats after mood, green skills, course and other bonuses.">Effective</span>
    {#each statKeys as stat}{@const value=effectiveStat(detail?.statBreakdown.stats[stat],motion.initialStats[stat])}<div class="effective-stat" class:ranged={detail?.statBreakdown.stats[stat].final===null} title={effectiveHelp(detail?.statBreakdown.stats[stat])} aria-label={`Effective ${statNames[stat]}: ${value}`}><strong>{value}</strong></div>{/each}
  </div>
  <div class="identity-facts"><StrategyBadge runner={displayRunner}/>{#if runner.mood!=null}<GameIcon name={`mood-${runner.mood}`} label={`${mood(runner.mood)} mood`} size={23}/>{/if}{#if runner.rankScore!=null}<span>Score {runner.rankScore}</span>{/if}{#if runner.starCount!=null}<StarRating count={runner.starCount}/>{/if}</div>
  <div class="aptitude-facts">{#each aptitudeFacts as [label,value]}<div><small>{label}</small>{#if aptitudeLetter(value)}<GameIcon name={`rank-${aptitudeLetter(value)}`} label={aptitudeLetter(value)??''} size={27}/>{:else}<span>—</span>{/if}</div>{/each}</div>
  <div class="detail-tabs"><button class:active={tab==='skills'} onclick={()=>tab='skills'}>Skills <span>{detail?.skillRows.length??0}</span></button><button class:active={tab==='stats'} onclick={()=>tab='stats'}>Stats</button><button class:active={tab==='events'} onclick={()=>tab='events'}>Statuses</button></div>
  {#if tab==='skills'}<div class="runner-skills">{#each skillRows as row}{@const levelLabel=uniqueLevelLabel(reference,runner,row.skillId)}<button class="acquired-skill" style={`--skill:${skillToneColor[skillTone(reference,row.skillId)]}`} onclick={()=>onSkill(row.skillId)}><GameIcon name={skillIconKey(reference,row.skillId)} size={22}/><strong>{skillName(reference,row.skillId)}{#if levelLabel}<span class="skill-level">{levelLabel}</span>{/if}</strong></button>{:else}<p class="muted">No skills recorded.</p>{/each}</div>
  {:else if tab==='stats'}<StatBreakdown breakdown={detail?.statBreakdown}/><RunnerEffects {detail} {race} {reference} {onSeek} {motion} {modes}/><div class="summary-stats">{#each metricGroups as [heading,rows]}<section><h3>{heading}</h3>{#each rows as [name,value,unit]}<div><span>{name}</span><strong>{value}{#if value!=='—'&&unit}<small>{unit}</small>{/if}</strong></div>{/each}</section>{/each}</div><section class="more-build"><h3>Aptitudes and build</h3>{#each aptitudeGroups as [heading,rows]}<div class="aptitude-group"><h4>{heading}</h4>{#each rows as [label,key]}<div><span>{label}</span>{#if aptitudeLetter(runner.aptitudes?.[key])}<GameIcon name={`rank-${aptitudeLetter(runner.aptitudes?.[key])}`} label={aptitudeLetter(runner.aptitudes?.[key])??''} size={22}/>{:else}<strong>—</strong>{/if}</div>{/each}</div>{/each}<div class="build-facts">{#if runner.raceWinCount!=null}<div><span>Career wins</span><strong>{runner.raceWinCount}</strong></div>{/if}{#if runner.fanCount!=null}<div><span>Fans</span><strong>{runner.fanCount.toLocaleString()}</strong></div>{/if}{#if runner.rankScore!=null}<div><span>Rank score</span><strong>{runner.rankScore}</strong></div>{/if}{#if runner.starCount!=null}<div><span>Stars</span><StarRating count={runner.starCount}/></div>{/if}</div></section><p class="panel-note">HP spent and gained are the sampled changes across the race. They are not the cost of one status.</p>
  {:else}<div class="status-totals">{#each detail?.statusImpacts.filter(s=>['spot-struggle','rushed','dueling'].includes(s.kind))??[] as impact}<div title={modelHelp}><strong>{statusShortLabel(impact.kind)} <span>{f(impact.duration)} s</span></strong><dl><dt>Distance bonus · model</dt><dd>{impact.modeledExtraDistance==null?'—':`${impact.modeledExtraDistance>=0?'+':''}${f(impact.modeledExtraDistance)} m`}</dd><dt>Extra HP cost · model</dt><dd>{f(impact.modeledExtraHp)}</dd><dt>HP spent in window</dt><dd>{f(impact.observedHpConsumed)}</dd>{#if impact.observedHpRecovered}<dt>HP recovered in window</dt><dd>+{f(impact.observedHpRecovered)}</dd>{/if}</dl></div>{/each}</div><div class="runner-status-list">{#each displayIntervals as interval}<button class:modeled={interval.evidence==='estimated'} title={interval.evidence==='simulated'?interval.detail:statusHelp(interval.kind)} onclick={()=>onSeek(interval.start)}><div><strong>{interval.label}</strong><span>{interval.start.toFixed(2)}s{interval.end!==null?`–${interval.end.toFixed(2)}s`:''}</span></div><small>{interval.evidence==='simulated'?'Simulator state':interval.evidence==='estimated'?'Calculated':interval.evidence==='recorded'?'Recorded status':'From replay samples'}</small>{#if interval.model}<div class="model-values">{#if interval.model.speedDelta!=null}<span>Speed {interval.model.speedDelta>=0?'+':''}{interval.model.speedDelta.toFixed(3)} m/s</span>{/if}{#if interval.model.speedMultiplier!=null}<span>Speed ×{interval.model.speedMultiplier.toFixed(3)}</span>{/if}{#if interval.model.hpDrainMultiplier!=null}<span>HP drain ×{interval.model.hpDrainMultiplier.toFixed(2)}</span>{/if}{#if interval.model.observedHpRate!=null}<span>Observed {interval.model.observedHpRate.toFixed(2)} HP/s</span>{/if}{#if interval.model.baselineHpRate!=null}<span>Baseline model {interval.model.baselineHpRate.toFixed(2)} HP/s</span>{/if}</div>{/if}{#if interval.impact}<div class="model-values" title={modelHelp}>{#if interval.impact.modeledExtraDistance!=null}<span>Distance bonus {interval.impact.modeledExtraDistance>=0?'+':''}{f(interval.impact.modeledExtraDistance)} m · model</span>{/if}{#if interval.impact.modeledExtraHp!=null}<span>Extra HP {f(interval.impact.modeledExtraHp)} · model</span>{/if}<span>HP spent {f(interval.impact.observedHpConsumed)}</span></div>{/if}</button>{:else}<p class="muted">No statuses detected.</p>{/each}</div>{/if}
</aside>
<style>
.effective-stat.ranged strong{font-size:var(--font-10);white-space:nowrap}
.effective-label{grid-column:1/-1;text-align:left;font-size:var(--font-9);color:var(--muted);border-top:1px solid var(--border);padding-top:7px;margin-top:5px}.effective-stat{color:var(--accent-text,var(--accent));font-variant-numeric:tabular-nums;cursor:help}
.runner-panel{align-self:stretch;flex:none;overflow:visible}.runner-panel-header{padding:16px;border-bottom:1px solid var(--border)}.runner-panel-header .eyebrow{margin-bottom:12px}.runner-identity{gap:10px}.runner-identity h2{font-size:var(--font-18)}.runner-identity .muted{font-size:var(--font-10);margin-top:5px;line-height:1.5}.runner-actions{display:flex;gap:6px;margin-top:15px;position:relative}.runner-actions button{flex:1;font-size:var(--font-10);padding:7px 5px}.live-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:15px 16px 10px}.live-stats small{display:block;font-size:var(--font-8);letter-spacing:.6px}.live-stats strong{font-size:var(--font-22);font-weight:550;font-variant-numeric:tabular-nums;line-height:1.7}.live-stats em{font-style:normal;font-size:var(--font-10);color:var(--muted);margin-left:4px}.active-statuses{padding:0 16px 12px;display:flex;gap:5px;flex-wrap:wrap}.active-statuses span{font-size:var(--font-9);background:color-mix(in srgb,var(--status) 18%,var(--panel));color:var(--text);border-left:2px solid var(--status);border-radius:3px;padding:4px 7px}.build-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:3px;padding:12px 13px;background:var(--bg);border-block:1px solid var(--border)}.build-stats>div{text-align:center}.build-stats small{display:block;font-size:var(--font-8);margin-bottom:5px}.build-stats strong{font-size:var(--font-15);font-weight:550}.identity-facts{display:flex;flex-wrap:wrap;gap:5px 12px;padding:12px 16px;font-size:var(--font-10);color:var(--muted)}.detail-tabs{gap:17px;padding:0 15px}.runner-skills{padding:8px 12px}.acquired-skill{display:flex;align-items:center;justify-content:flex-start;gap:8px;width:100%;margin:4px 0;border:1px solid transparent;border-radius:6px;background:color-mix(in srgb,var(--skill) 10%,transparent);text-align:left;white-space:normal;padding:10px 12px;cursor:pointer}.acquired-skill:hover{background:color-mix(in srgb,#000 16%,var(--panel));border-color:var(--skill)}.acquired-skill strong{font-size:var(--font-13);line-height:1.4;font-weight:550}.acquired-skill .skill-level{margin-left:6px;color:var(--muted);font-size:var(--font-11);font-weight:650;font-variant-numeric:tabular-nums}.summary-stats{padding:4px 16px 8px}.summary-stats section{padding:12px 0;border-bottom:1px solid var(--border)}.summary-stats h3{margin:0 0 6px;font-size:var(--font-12);font-weight:650}.summary-stats section>div{display:flex;justify-content:space-between;gap:12px;padding:5px 0;font-size:var(--font-13)}.summary-stats span{color:var(--muted)}.summary-stats strong{font-weight:550}.summary-stats small{margin-left:4px;color:var(--muted);font-weight:400}.more-build{padding:14px 16px 8px}.more-build h3{margin:0 0 10px;font-size:var(--font-13)}.aptitude-group{margin-bottom:12px}.aptitude-group h4{margin:0 0 6px;font-size:var(--font-11);color:var(--muted);font-weight:600;letter-spacing:.04em;text-transform:uppercase}.aptitude-group>div,.build-facts>div{display:flex;align-items:center;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--border);font-size:var(--font-13)}.build-facts{margin-top:8px}.panel-note{padding:0 16px 14px;font-size:var(--font-12);line-height:1.5;color:var(--muted)}.runner-status-list{padding:8px 14px}.runner-status-list button{width:100%;display:block;background:none;border:0;border-bottom:1px solid var(--border);white-space:normal;padding:12px 0;text-align:left}.runner-status-list button>div{display:flex;justify-content:space-between;gap:12px;font-size:var(--font-11)}.runner-status-list button span{font-size:var(--font-10);color:var(--muted)}.runner-status-list small{display:block;line-height:1.6;margin-top:5px}.model-values{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}.model-values span{background:var(--accent-soft);padding:4px 6px;border-radius:3px}.runner-status-list button.modeled{border-bottom-style:dashed}@media(max-width:1100px){.runner-panel{position:static;max-height:none}}
.build-stats small{margin:4px 0}.aptitude-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;padding:0 14px 12px}.aptitude-facts>div{display:flex;align-items:center;justify-content:space-between;padding:7px 8px;background:var(--bg);border:1px solid var(--border);border-radius:5px}.aptitude-facts small{font-size:var(--font-9)}.runner-panel-header{padding:13px}.runner-identity h2{font-size:var(--font-17)}.runner-actions{margin-top:10px}.live-stats{gap:8px;padding:12px 14px 8px}.live-stats strong{font-size:var(--font-20)}.runner-skills{padding:8px 12px}.identity-facts{align-items:center;padding:10px 14px}.more-build :global(.game-icon){max-height:22px}
.status-totals{padding:0 14px}.status-totals>div{padding:12px 0;border-bottom:1px solid var(--border)}.status-totals strong{display:flex;justify-content:space-between;font-size:var(--font-12)}.status-totals strong span{color:var(--muted);font-size:var(--font-11);font-weight:400}.status-totals dl{display:grid;grid-template-columns:1fr auto;gap:6px;margin:9px 0 0;font-size:var(--font-10)}.status-totals dt{color:var(--muted)}.status-totals dd{margin:0;font-variant-numeric:tabular-nums}
.runner-actions{flex-wrap:wrap}.runner-actions button{white-space:normal;min-width:0}
.live-stats{grid-template-columns:repeat(auto-fit,minmax(min(100%,calc(100px * var(--font-scale))),1fr))}
.live-stats>div{min-width:0}.live-stats strong{overflow-wrap:anywhere}.build-stats{overflow-x:auto}
.aptitude-facts{grid-template-columns:repeat(auto-fit,minmax(min(100%,calc(70px * var(--font-scale))),1fr))}
.detail-tabs{flex-wrap:wrap}.runner-identity>div{min-width:0;overflow-wrap:anywhere}
</style>
